import java.util.ArrayList;
import java.util.List;

class Fibonacci {

    public static List<Long> generateFibonacci(int count) {
        if (count <= 0) {
            return new ArrayList<>();
        }

        List<Long> fibonacciSequence = new ArrayList<>();
        fibonacciSequence.add(0L);
        if (count > 1) {
            fibonacciSequence.add(1L);
        }

        for (int i = 2; i < count; i++) {
            long nextFib = fibonacciSequence.get(i - 1) + fibonacciSequence.get(i - 2);
            fibonacciSequence.add(nextFib);
        }

        return fibonacciSequence;
    }


    public static List<Long> generateFibonacciUpToLimit(long limit) {
        List<Long> fibonacciSequence = new ArrayList<>();
        long a = 0, b = 1;
        fibonacciSequence.add(a);
        if (limit > 0) {
          fibonacciSequence.add(b);
        }

        while (b <= limit) {
            long nextFib = a + b;
            a = b;
            b = nextFib;
            fibonacciSequence.add(b);
        }
        return fibonacciSequence;
    }


    public static void main(String[] args) {
        int count = 10;
        List<Long> fibonacciSequence = generateFibonacci(count);
        System.out.println("First " + count + " Fibonacci numbers: " + fibonacciSequence);


        long limit = 1000;
        List<Long> fibSequenceUpToLimit = generateFibonacciUpToLimit(limit);
        System.out.println("Fibonacci numbers up to " + limit + ": " + fibSequenceUpToLimit);
    }
}
```

